static const char *const k_alias_keys[] = { "sleeping", "waking", "idle", "curious", "spacing_out", "booting", "dormant", "shake_awake", "happy", "puzzled", "down", "surprised", "shy", "tired", "focused", "panicked", "resigned", "satisfied", "confused", "angry", "thinking", "receiving", "busy", "done", "error", "listening", "loading", "recalling", "refusing", "replying", "searching", "powering_off", "music" };
static const char *const k_alias_vals[] = { "SLEEP", "WAKE", "IDLE", "CURIOUS", "CALM", "UPDATE", "SLEEP", "WAKE", "HAPPY", "PUZZLED", "SAD", "SURPRISED", "SHY", "TIRED", "THINKING", "SURPRISED", "SAD", "SATISFIED", "CONFUSED", "ANGRY", "THINKING", "WAITING", "CODING", "SUCCESS", "ERROR", "LISTENING", "RECONNECTING", "READING", "WARNING", "SPEAKING", "SEARCHING", "SLEEP", "MUSIC" };

const dotii_expr_t *dotii_catalog_by_id(const char *id)
{
    if (id == NULL) return NULL;
    for (size_t i = 0; i < DOTII_EXPR_COUNT; ++i) {
        if (k_expressions[i].id[0] == id[0] && k_expressions[i].id[1] == id[1] && id[2] == '\0') return &k_expressions[i];
    }
    return NULL;
}

const dotii_expr_t *dotii_catalog_by_name(const char *name)
{
    if (name == NULL) return NULL;
    for (size_t i = 0; i < DOTII_EXPR_COUNT; ++i) {
        const char *a = k_expressions[i].name;
        const char *b = name;
        while (*a && *b && (*a == *b || (*a ^ *b) == 0x20)) { ++a; ++b; }
        if (*a == '\0' && *b == '\0') return &k_expressions[i];
    }
    return NULL;
}

const dotii_expr_t *dotii_catalog_at(size_t index)
{
    return index < DOTII_EXPR_COUNT ? &k_expressions[index] : NULL;
}

size_t dotii_catalog_count(void) { return DOTII_EXPR_COUNT; }

const dotii_expr_t *dotii_catalog_idle(void) { return &k_expressions[0]; }

const char *dotii_alias_resolve(const char *legacy_name)
{
    if (legacy_name == NULL) return NULL;
    for (size_t i = 0; i < sizeof(k_alias_keys) / sizeof(k_alias_keys[0]); ++i) {
        const char *a = k_alias_keys[i];
        const char *b = legacy_name;
        while (*a && *b && *a == *b) { ++a; ++b; }
        if (*a == '\0' && *b == '\0') return k_alias_vals[i];
    }
    return NULL;
}
